local({
  items <- cbind(as.numeric(fasting_30d), as.numeric(diet_pills_30d), as.numeric(vomit_laxatives_30d))
  case_when(
    rowSums(items == 1, na.rm = TRUE) > 0 ~ "TRUE",
    rowSums(items == 2, na.rm = TRUE) > 0 ~ "FALSE",
    .default = NA_character_
  )
})

local({
  feet_inches <- if_else(grepl("^[3-7](0[0-9]|1[01])$", height_orig), height_orig, NA_character_)
  inches <- as.numeric(substr(feet_inches, 1, 1)) * 12 + as.numeric(substr(feet_inches, 2, 3))
  pounds <- na_if(as.numeric(if_else(grepl("^[0-9]+$", weight_orig), weight_orig, NA_character_)), 0)
  if_else(
    as.character(.wave) %in% c("2013", "2015", "2017", "2019"),
    pounds * 0.4536 / (inches * 0.0254)^2,
    weight_kg / height_m^2
  )
})
